from scipy.optimize import minimize_scalar
fams={
 'tanh':lambda k: np.tanh(k*t),
 'expo':lambda k: 1-np.exp(-k*t),
 'hyp':lambda k: t/(t+k),
 'sqrt':lambda k: np.sqrt(t)/(np.sqrt(t)+k),
 'powsat':lambda k: 1-np.exp(-k*t**1.0)*0,  
 'logi':lambda k: 1/(1+np.exp(-k*(t-6))),
 'atan':lambda k: np.arctan(k*t),
}
def sparse(G):
    cols=[G,P,P*t,P**2,P**2*t,P*G,P**2*G,P**3,np.ones_like(t),t,t*G]
    X=np.array(cols).T
    c=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((X@c-dP_dt)**2)/np.var(dP_dt),c
for name,f in fams.items():
    best=None
    for k in np.geomspace(0.02,20,300):
        try:
            v,_=sparse(f(k))
        except Exception: continue
        if np.isfinite(v) and (best is None or v<best[0]): best=(v,k)
    if best:
        r=minimize_scalar(lambda kk: sparse(f(kk))[0],bounds=(best[1]*0.8,best[1]*1.25),method='bounded')
        print(name,r.x,r.fun)

from scipy.optimize import minimize_scalar
def rich(k,form='tanh'):
    G=np.tanh(k*t) if form=='tanh' else 1-np.exp(-k*t)
    cols=[]
    for j in range(4):
        for f in [1,G,t,t*G,t*t]:
            cols.append(P**j*f)
    X=np.array(cols).T
    c=np.linalg.lstsq(X,dP_dt,rcond=None)[0]
    return np.mean((X@c-dP_dt)**2)/np.var(dP_dt),c,X
for form in ['tanh','exp']:
    r=minimize_scalar(lambda k: rich(k,form)[0],bounds=(0.05,1.0),method='bounded',options={'xatol':1e-10})
    print(form,r.x,r.fun)

